INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(25701, 'John 19:3', 'John', 19, 3, '&nbsp;هغوئ هغۀ له راتلل، او ورته يې وئيل، ”اے د يهوديانو بادشاه سلامت.“ او په مخ به يې څپېړه ورکوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25702, 'John 19:4', 'John', 19, 4, '&nbsp;يو ځل بيا پيلاطوس بهر راوتو او يهوديانو ته يې ووئيل چې، ”وګورئ زۀ هغه تاسو له بهر راولم چې تاسو خبر شئ چې ما د هغۀ خلاف هيڅ جرم ونۀ موندلو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25703, 'John 19:5', 'John', 19, 5, '&nbsp;نو عيسىٰ بهر راغلو د ازغو تاج يې په سر وو او کاسنى چُوغه يې اغوستې وه. پيلاطوس هغوئ ته ووئيل، ”وګورئ، دا هغه سړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25704, 'John 19:6', 'John', 19, 6, '&nbsp;کله چې مشرانو اِمامانو او د خُدائ د کور محافظانو هغه وليدو هغوئ چغې کړې، ”دے په سولۍ راځوړند کړئ. دے په سولۍ راځوړند کړئ.“ پيلاطوس هغوئ ته ووئيل چې، ”دے بوځئ او په خپله يې په سولۍ کړئ ځکه چې ما د دۀ خلاف هيڅ جرم ونۀ موندلو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25705, 'John 19:7', 'John', 19, 7, '&nbsp;يهوديانو هغۀ ته جواب ورکړو چې، ”مونږ سره شريعت شته، او د هغه شريعت په مطابق دے د مرګ لائق دے ځکه چې دۀ د خُدائ پاک د زوئ کېدو دعوىٰ کړې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25706, 'John 19:8', 'John', 19, 8, '&nbsp;کله چې پيلاطوس دا واورېدل نو هغه نور زيات يرې واخستلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25707, 'John 19:9', 'John', 19, 9, '&nbsp;هغه خپلې قلعې ته بيا دننه شو او د عيسىٰ نه يې تپوس وکړو چې، ”تۀ د کوم ځائ نه راغلے يې؟“ خو عيسىٰ ورته هيڅ جواب ورنۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25708, 'John 19:10', 'John', 19, 10, '&nbsp;نو پيلاطوس هغۀ ته ووئيل، ”تۀ ما سره خبرې نۀ کوې څۀ؟ تا ته دا معلومه نۀ ده چې ما سره دا اختيار شته چې تا آزاد کړم او دا اختيار هم راسره شته چې تا په سولۍ کړم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25709, 'John 19:11', 'John', 19, 11, '&nbsp;عيسىٰ هغۀ ته جواب ورکړو چې، ”ستا به په ما باندې هيڅ اختيار نۀ وے کۀ چرې دا د بره نه تا ته نۀ وے درکړے شوے. په دې وجه چا چې زۀ تا ته په حواله کړے يم، هغه د لوئ ګناه مجرم دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25710, 'John 19:12', 'John', 19, 12, '&nbsp;د هغه ساعت نه پس پيلاطوس ډېر کوشش کولو چې هغه آزاد کړى خو يهوديانو چغې وهلې، ”کۀ تا دا سړے آزاد کړو نو تۀ د رومى قيصر خير خواه نۀ يې. هر څوک چې د بادشاه کېدو دعوىٰ کوى هغه د رومى قيصر مخالفت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25711, 'John 19:13', 'John', 19, 13, '&nbsp;کله چې پيلاطوس دا خبرې واورېدلې نو هغۀ عيسىٰ بهر راوويستو او د عدالت په کُرسۍ هغه ځائ کښېناستو چې دونکاچه ورته وائى يا په آرامى ژبه کښې ورته ګبتا وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25712, 'John 19:14', 'John', 19, 14, '&nbsp;د غرمې په وخت کښې چې د فسح اختر د تيارولو ورځ وه، پيلاطوس يهوديانو ته ووئيل، ”وګورئ، دا دے ستاسو بادشاه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25713, 'John 19:15', 'John', 19, 15, '&nbsp;هغوئ چغې سورې جوړې کړې، ”بو يې ځئ، بو يې ځئ. په سولۍ يې کړه.“ پيلاطوس هغوئ نه تپوس وکړو، ”ستاسو بادشاه په سولۍ کړم څۀ؟“ مشرانو اِمامانو جواب ورکړو چې، ”زمونږ خو د قيصر نه بغېر بل بادشاه نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25714, 'John 19:16', 'John', 19, 16, '&nbsp;بيا پيلاطوس عيسىٰ هغوئ ته د سولۍ کولو دپاره په حواله کړو. نو هغوئ عيسىٰ بوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25715, 'John 19:17', 'John', 19, 17, '&nbsp;او هغۀ خپله سولۍ په خپله پورته کړې وه، او هغه بهر هغه ځائ ته لاړو چې ورته د کوپړو ځائ وائى، او په آرامى ژبه کښې ورته ګولګتا وائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25716, 'John 19:18', 'John', 19, 18, '&nbsp;هلته هغوئ هغه په سولۍ کړو او ورسره يې دوه نور هم، يو ښى لاس ته او بل ګس لاس ته، او عيسىٰ د هغوئ په مينځ کښې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25717, 'John 19:19', 'John', 19, 19, '&nbsp;پيلاطوس په سولۍ د يوې تختې لګولو حکم ورکړو چې پرې دا ليک وو، ”عيسىٰ ناصرى د يهوديانو بادشاه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25718, 'John 19:20', 'John', 19, 20, '&nbsp;ډېرو يهوديانو دا تختۍ ولوستله ځکه چې هغه ځائ چې چرته عيسىٰ په سولۍ کړے شو هغه ښار ته نزدې وو، او هغه تختۍ په آرامى، لاطينى او يونانى ژبه کښې ليکلے شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25719, 'John 19:21', 'John', 19, 21, '&nbsp;بيا د يهوديانو مشرانو اِمامانو پيلاطوس ته ووئيل، ”دا مۀ ليکئ چې د يهوديانو بادشاه، بلکې داسې وليکئ چې، دۀ وئيلى وُو چې زۀ په خپله د يهوديانو بادشاه يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25720, 'John 19:22', 'John', 19, 22, '&nbsp;پيلاطوس جواب ورکړو، ”نه، د کومو ليکلو چې ما حکم ورکړے دے هغه ټيک دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25721, 'John 19:23', 'John', 19, 23, '&nbsp;کله چې سپاهيانو عيسىٰ په سولۍ کړو، هغوئ د هغۀ جامې راواخستې او په څلورو برخو يې تقسيم کړې، د هر يو سپاهى دپاره يوه برخه، او چُوغه يې روغه پرېښوده. ځکه چُوغه لا ګنډلے شوې نۀ وه او د سر نه تر ښکته پورې ټوله د يوې ټوټې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25722, 'John 19:24', 'John', 19, 24, '&nbsp;نو هغوئ يو بل ته ووئيل، ”مونږ ته دا څيرى کول نۀ دى په کار، راځئ چې پرې پچه واچوو، وبه ګورو چې د چا رسيږى.“ دغه شان د صحيفې ليک پوره شو چې، ”هغوئ زما جامې په خپلو کښې تقسيم کړې او زما په چُوغه يې پچه واچوله.“ هم دغه شان سپاهيانو وکړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25723, 'John 19:25', 'John', 19, 25, '&nbsp;خو د عيسىٰ د سولۍ سره نزدې د هغۀ مور او ترور او د کلوپاس ښځه مريم او مريم مګدلينى ولاړې وې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25724, 'John 19:26', 'John', 19, 26, '&nbsp;کله چې عيسىٰ خپله مور د خپل خوږ مريد سره په خوا کښې ولاړه وليده عيسىٰ هغې ته وفرمائيل، ”مورې، دا ستا زوئ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25725, 'John 19:27', 'John', 19, 27, '&nbsp;هغۀ بيا مريد ته وفرمائيل، ”دغه ستا مور ده.“ د هغه وخت نه پس هغه مريد هغه خپل کور ته بوتله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25726, 'John 19:28', 'John', 19, 28, '&nbsp;د دې نه پس عيسىٰ چې پوهه شو چې هر څۀ پوره شوى دى نو هغۀ وفرمائيل، ”زۀ تږے يم.“ او دې سره د صحيفې يوه پېشګوئې پوره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25727, 'John 19:29', 'John', 19, 29, '&nbsp;هلته يو لوښے د تروې سرکې نه ډک پروت وو. نو هغوئ يو اسفنج په کښې لوند کړو او د ويلنې په څانګه يې کېښودو او دا يې د عيسىٰ شونډو ته ورورسولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25728, 'John 19:30', 'John', 19, 30, '&nbsp;کله چې سرکه عيسىٰ ته ورکړے شوه نو هغۀ وفرمائيل چې، ”دا کار پوره شو.“ بيا يې سر ټيټ کړو او ساه يې ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25729, 'John 19:31', 'John', 19, 31, '&nbsp;اوس دا د فسح دپاره د تيارۍ کولو د جمعې ورځ وه او راتلونکې ورځ د خاص سبت وه. په دې وجه يهوديانو نۀ غوښتل چې د سبت په ورځ دې مړى په سولۍ پاتې شى، نو هغوئ پيلاطوس ته خواست وکړو چې د دوئ پښې دې ماتې کړے شى او مړى دې راکوز کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25730, 'John 19:32', 'John', 19, 32, '&nbsp;نو سپاهيان راغلل او د اولنى سړى پښې يې ماتې کړې او بيا يې د هغه بل سړى پښې ماتې کړې چې عيسىٰ سره په سولۍ شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25731, 'John 19:33', 'John', 19, 33, '&nbsp;خو کله چې هغوئ عيسىٰ له راغلل او وې ليدو چې هغه د اول نه مړ دے، نو هغوئ د هغۀ پښې ماتې نۀ کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25732, 'John 19:34', 'John', 19, 34, '&nbsp;خو د دې باوجود يو سپاهى د هغۀ پوښتۍ په نېزه ووهله او سمدستى ترې د وينو او اوبو دارې روانې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25733, 'John 19:35', 'John', 19, 35, '&nbsp;هغه سړى چې دا وکتل هغۀ ګواهى ورکړه او د هغۀ ګواهى رښتيا ده. هغه رښتيا خبرې کوى د دې دپاره چې تاسو هم ايمان راوړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25734, 'John 19:36', 'John', 19, 36, '&nbsp;دا کارونه وشول نو چې د صحيفې وينا پوره شى چې، ”د هغۀ يو هډوکے به هم مات نۀ کړے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25735, 'John 19:37', 'John', 19, 37, '&nbsp;او بيا په يو بل آيت کښې راغلى دى چې، ”هغوئ به هغه سړى ته ګورى چې په نېزه يې سورے کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25736, 'John 19:38', 'John', 19, 38, '&nbsp;د هغې نه پس يوسف چې د ارمتيه وو د پيلاطوس نه د عيسىٰ د مړى وړلو خواست وکړو. يوسف د عيسىٰ مريد وو خو په پټه ځکه چې هغه د يهوديانو نه يرېدو. د پيلاطوس په اجازت سره هغه راغلو او د هغۀ مړے يې يوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25737, 'John 19:39', 'John', 19, 39, '&nbsp;د هغۀ سره نيکوديموس نومې سړے هم ملګرے شو څوک چې عيسىٰ له د شپې ورغلے وو، او نيکوديموس تقريباً د پنځوس سېره د مُر چيړ سره د عُودو ګډ کړى راوړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25738, 'John 19:40', 'John', 19, 40, '&nbsp;هغوئ دواړو د عيسىٰ لاش واخستو او د يهوديانو د ښخولو د رِواج په مطابق يې خوشبودار د کتان کفن کښې ونغښتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25739, 'John 19:41', 'John', 19, 41, '&nbsp;په کوم ځائ کښې چې عيسىٰ په سولۍ کړے شوے وو هلته کښې يو باغ وو او په باغ کښې دننه يو نوے قبر وو چې د دې نه وړاندې په کښې لا څوک ښخ شوى نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25740, 'John 19:42', 'John', 19, 42, '&nbsp;ځکه چې دا د يهوديانو د فسح د تيارۍ ورځ وه او دا قبر د هغه ځائ سره نزدې وو نو هغوئ عيسىٰ په دې کښې کېښودو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25741, 'John 20:1', 'John', 20, 1, '&nbsp;د اِتوار په ورځ سحر وختى چې لا توره خړه وه مريم مګدلينى قبر له لاړه او وې کتل چې د غار د خولې نه کاڼے لرې کړے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25742, 'John 20:2', 'John', 20, 2, '&nbsp;نو هغه په منډه شمعون پطروس او هغه بل مريد له راغله چا سره چې عيسىٰ مينه کوله او ورته يې ووئيل چې، ”هغوئ مالِک د قبر نه وړے دے، او مونږ ته دا پته نشته چې کوم ځائ هغوئ د هغۀ لاش ښخ کړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25743, 'John 20:3', 'John', 20, 3, '&nbsp;نو پطروس او هغه بل مريد راووتل او قبر طرف ته روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25744, 'John 20:4', 'John', 20, 4, '&nbsp;هغوئ دواړو يو ځائ منډې وهلې خو هغه بل مريد د پطروس نه مخکښې شو او قبر ته وړاندې ورسېدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25745, 'John 20:5', 'John', 20, 5, '&nbsp;هغۀ سر ټيټ کړو او دننه يې وکتل چې د کتان کفن هلته پروت وو خو دننه ورنۀغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25746, 'John 20:6', 'John', 20, 6, '&nbsp;بيا شمعون پطروس چې په هغۀ پسې وو راورسېدو او غار ته ورننوتو. د کتان هغه کفن يې هلته پروت وليدو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25747, 'John 20:7', 'John', 20, 7, '&nbsp;او هغه رومال چې د عيسىٰ سر يې پرې تړلے وو د کتان د کفن سره نۀ وو بلکې ځان له جدا انغښتے شوے په يو بل ځائ کښې پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25748, 'John 20:8', 'John', 20, 8, '&nbsp;بيا هغه بل مريد څوک چې قبر ته مخکښې رسېدلے وو هغه هم قبر ته ورننوتو او وې ليدل او يقين يې پرې وکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25749, 'John 20:9', 'John', 20, 9, '&nbsp;نو اوس هم هغوئ د صحيفو په مطلب پوهه نۀ وُو چې عيسىٰ به خامخا د مړو نه بيا ژوندے پاڅى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25750, 'John 20:10', 'John', 20, 10, '&nbsp;نو مريدان واپس خپلو کورونو ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25751, 'John 20:11', 'John', 20, 11, '&nbsp;خو مريم د قبر نه بهر ولاړه وه او ژړل يې. او په ژړا کښې هغه ورټيټه شوه چې غار کښې دننه وګورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25752, 'John 20:12', 'John', 20, 12, '&nbsp;او هغې هلته دوه فرښتې په سپينو جامو کښې د لاش په ځائ ناستې وليدې، يوه سر ته او بله پښو ته، په هغه ځائ کښې چرته چې د عيسىٰ لاش کېښودے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25753, 'John 20:13', 'John', 20, 13, '&nbsp;هغوئ د هغې نه تپوس وکړو چې، ”اے خورې، تۀ ولې ژاړې؟“ هغې جواب ورکړو چې، ”هغوئ زما مالِک چرته اوړے دے او ما ته پته نشته چې هغه يې کوم ځائ ښخ کړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25754, 'John 20:14', 'John', 20, 14, '&nbsp;د دې خبرو نه پس هغې مخ راواړولو او عيسىٰ يې هلته ولاړ وليدو، خو هغې ونۀ پېژندلو چې دا عيسىٰ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25755, 'John 20:15', 'John', 20, 15, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”اے خورې، تۀ ولې ژاړې؟ تۀ څوک لټوې؟“ هغې دا خيال وکړو چې دا د دې باغ مالى دے، نو ورته يې ووئيل، ”صاحبه، کۀ چرې تا هغه د دې ځائ نه وړے وى نو ما ته ووايه چې هغه دې کوم ځائ ښخ کړے دے، او زۀ به هغه يوسم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25756, 'John 20:16', 'John', 20, 16, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”مريمې.“ هغې هغۀ ته مخ ورواړولو او په آرامى ژبه کښې يې وئيل، ”ربونى.“ چې مطلب يې اُستاذ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25757, 'John 20:17', 'John', 20, 17, '&nbsp;عيسىٰ هغې ته وفرمائيل، ”ګوره چې ما ته لاس رانۀ وړې ځکه چې زۀ لا خپل پلار ته نۀ يم ورغلے. خو زما وروڼو له لاړه شه او هغوئ ته ووايه چې زۀ خپل پلار له او ستاسو پلار له، خپل خُدائ پاک له او ستاسو خُدائ پاک له پاس ځم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25758, 'John 20:18', 'John', 20, 18, '&nbsp;مريم مګدلينى مريدانو له لاړه او وې وئيل چې، ”ما مالِک وليدو.“ او هغې هغوئ ته د هغه هر څۀ حال ووئيلو څۀ چې عيسىٰ ورته فرمائيلى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25759, 'John 20:19', 'John', 20, 19, '&nbsp;د پير په شپه چې مريدانو د يهوديانو د يرې نه دروازې بندې کړې وې ناست وُو، چې په دې کښې عيسىٰ راغلو، د هغوئ په مينځ کښې ودرېدو او ورته يې وفرمائيل، ”السلام عليکم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25760, 'John 20:20', 'John', 20, 20, '&nbsp;د دې نه پس هغۀ هغوئ ته خپل لاسونه او خپله پښتۍ وښودله. نو چې کله مريدانو مالِک وليدو نو هغوئ ډېر خوشحاله شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25761, 'John 20:21', 'John', 20, 21, '&nbsp;عيسىٰ يو ځل بيا وفرمائيل چې، ”په تاسو دې سلامتيا وى، څنګه چې پلار زۀ رالېږلے يم هم دغسې زۀ تاسو لېږم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25762, 'John 20:22', 'John', 20, 22, '&nbsp;بيا يې په هغوئ وپوکل او وې فرمائيل، ”زما له خوا نه روحُ القُدس قبول کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25763, 'John 20:23', 'John', 20, 23, '&nbsp;کۀ چرې تاسو د چا ګناهونه وبخښئ نو هغوئ به وبخښلے شى، او کۀ تاسو هغوئ ونۀ بخښئ نو هغوئ به ونۀ بخښلے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25764, 'John 20:24', 'John', 20, 24, '&nbsp;په دولسو مريدانو کښې يو توما چې برغونے هم بللے شى کله چې عيسىٰ راغے هغه د نورو سره موجود نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25765, 'John 20:25', 'John', 20, 25, '&nbsp;نو نورو مريدانو هغۀ ته ووئيل چې، ”مونږ مالِک وليدلو.“ خو توما هغوئ ته ووئيل چې، ”ترڅو چې ما د هغۀ په لاس کښې د مېخونو زخمونه ليدلى نۀ وى او د مېخونو په زخمونو مې ګوتې وهلې نۀ وى، او خپل لاس مې د هغۀ په پښتۍ نۀ وى لګولے نو زۀ به په دې هيڅکله يقين ونۀ کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25766, 'John 20:26', 'John', 20, 26, '&nbsp;اتۀ ورځې پس د هغۀ مريدان بيا په هماغه کور کښې دننه راجمع وُو او توما هم د هغوئ سره موجود وو. اګر کۀ دروازې تالا وې خو عيسىٰ راغلو د هغوئ په مينځ کښې ودرېدو او وې فرمائيل، ”په تاسو دې سلامتيا وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25767, 'John 20:27', 'John', 20, 27, '&nbsp;بيا هغۀ توما ته وفرمائيل، ”خپلې ګوتې دلته کېږده او زما لاسونه ووينه او خپل لاس راوړاندې کړه او زما په پښتۍ يې ولګوه. نور شک مۀ کوه خو يقين کوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25768, 'John 20:28', 'John', 20, 28, '&nbsp;توما هغۀ ته ووئيل، ”زما مالِکه او زما خُدايه پاکه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25769, 'John 20:29', 'John', 20, 29, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”په دې چې تا زۀ وليدم نو ايمان دې راوړو. بختور دى هغوئ چا چې زۀ نۀ يم ليدلے او ايمان يې راوړے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25770, 'John 20:30', 'John', 20, 30, '&nbsp;عيسىٰ د خپلو مريدانو په موجودګۍ کښې نورې هم ډيرې معجزې څرګندې کړې دى، کومې چې په دې کِتاب کښې نۀ دى ليکلے شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25771, 'John 20:31', 'John', 20, 31, '&nbsp;خو دا يو څو معجزې ځکه ليکلے شوې دى چې تاسو په دې ايمان راوړئ چې عيسىٰ هم مسيح، يعنې د خُدائ پاک زوئ دے، او چې د ايمان راوړلو په وسيله تاسو ته د هغۀ په نوم ژوندون مِلاو شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25772, 'John 21:1', 'John', 21, 1, '&nbsp;څۀ موده پس عيسىٰ بيا د ګليل د درياب په غاړه مريدانو ته خپل ځان څرګند کړو. هغه په دې طريقه څرګند شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25773, 'John 21:2', 'John', 21, 2, '&nbsp;شمعون پطروس او توما چې غبرګونے هم بللے کيږى او نتنى‌ايل چې د ګليل د قانا وو او د زبدى زامن، او دوه نور مريدان هم هلته موجود وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25774, 'John 21:3', 'John', 21, 3, '&nbsp;شمعون پطروس هغوئ ته ووئيل، ”زۀ د کبانو ښکار له ځم.“ نو هغوئ ورته ووئيل چې، ”مونږ به هم درسره ځو.“ هغوئ روان شول او کشتۍ ته وختل خو په هغه شپه هغوئ هيڅ ونۀ نيول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25775, 'John 21:4', 'John', 21, 4, '&nbsp;چې سحر شو نو عيسىٰ د درياب په غاړه ولاړ وو خو مريدانو ته دا پته نۀ وه چې دا عيسىٰ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25776, 'John 21:5', 'John', 21, 5, '&nbsp;عيسىٰ هغوئ ته نعرې کړې، ”اے دوستانو، تاسو څۀ کبان ونيول کۀ نه؟“ هغوئ جواب ورکړو چې، ”نه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25777, 'John 21:6', 'John', 21, 6, '&nbsp;هغوئ ته يې وفرمائيل، ”د کِشتۍ ښى طرف ته جال وولئ نو تاسو به څۀ کبان ونيسئ.“ کله چې هغوئ جال وغورزولو نو هغوئ جال کِشتۍ ته نۀ شو راخېژولے ځکه چې په هغې کښې ډېر زيات کبان راګېر شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25778, 'John 21:7', 'John', 21, 7, '&nbsp;بيا هغه مريد چې عيسىٰ ورسره مينه کوله پطروس ته ووئيل، ”دا خو مالِک دے.“ کله چې شمعون پطروس دا واورېدل چې دا مالِک دے نو هغۀ زر خپل قميص واچولو ځکه چې هغۀ خپل قميص کوز کړے وو او درياب ته يې ودانګل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25779, 'John 21:8', 'John', 21, 8, '&nbsp;خو نور مريدان په کِشتۍ کښې راغلل او د کبانو ډک جال يې راښکو ځکه چې هغوئ د وچې زمکې نه لرې نۀ وُو خو تقريباً يو سل ګزه به وراخوا وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25780, 'John 21:9', 'John', 21, 9, '&nbsp;کله چې هغوئ غاړې ته راوختل نو هغوئ د سکرو اور وليدو چې دپاسه پرې کبان او لږه روټۍ پرته وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25781, 'John 21:10', 'John', 21, 10, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”د خپلو هغه کبانو نه چې اوس مو ونيول څۀ راوړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25782, 'John 21:11', 'John', 21, 11, '&nbsp;نو شمعون پطروس کِشتۍ ته ورغلو او جال يې زمکې ته راښکلو چې د غټو کبانو نه ډک وو، او دا يو سل درې پنځوس وُو، او سره د دې چې دومره زيات وُو خو بيا هم جال ونۀ شلېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25783, 'John 21:12', 'John', 21, 12, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”راشئ او ناشته وکړئ.“ په مريدانو کښې يو کس هم دا همت ونۀ کړو چې تپوس ترې وکړى چې، ”تۀ څوک يې؟“ ځکه چې هغوئ ته دا پته وه چې دا مالِک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25784, 'John 21:13', 'John', 21, 13, '&nbsp;عيسىٰ راغلو، او روټۍ يې واخسته او هغوئ له يې ورکړه او هم دغه شان يې کبان هم تقسيم کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25785, 'John 21:14', 'John', 21, 14, '&nbsp;اوس دا درېم ځل وو چې عيسىٰ د مړو نه د ژوندى کېدو نه وروستو مريدانو ته ځان څرګند کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25786, 'John 21:15', 'John', 21, 15, '&nbsp;د ناشتې نه پس عيسىٰ شمعون پطروس ته وفرمائيل، ”شمعونه د يوحنا زويه، تۀ د نورو ټولو نه ما سره زياته مينه کوې څۀ؟“ هغۀ جواب ورکړو چې، ”آو مالِکه، تا ته پته ده چې زۀ تا سره مينه کوم.“ عيسىٰ هغۀ ته وفرمائيل چې، ”نو بيا زما ګډورى وڅروه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25787, 'John 21:16', 'John', 21, 16, '&nbsp;په دوېم ځل هغۀ ورته وفرمائيل چې، ”شمعون د يوحنا زويه، تۀ ما سره مينه کوې؟“ پطروس ورته ووئيل، ”آو، مالِکه، تا ته ښۀ پته ده چې زۀ تا سره مينه کوم.“ عيسىٰ ورته وفرمائيل، ”نو بيا زما ګډې سمبالې کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25788, 'John 21:17', 'John', 21, 17, '&nbsp;په درېم ځل عيسىٰ هغۀ ته وفرمائيل چې، ”شمعون د يوحنا زويه، تۀ ما سره مينه کوې؟“ پطروس په دې خبره غمژن شو ځکه چې هغۀ ترې په درېم ځل دا تپوس وکړو چې، ”تۀ ما سره مينه کوې؟“ هغۀ ووئيل، ”مالِکه، تا ته د هر څۀ ښۀ پته ده. تۀ په دې پوهېږې چې زۀ تا سره مينه کوم.“ عيسىٰ وفرمائيل، ”زما ګډې وڅروه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25789, 'John 21:18', 'John', 21, 18, '&nbsp;زۀ تا ته رښتيا وايم چې کله چې تۀ ځوان وې نو تا به خپله ملا په خپله تړله او چرته چې به دې خوښه وه هلته به تللې، خو کله چې تۀ زوړ شې نو تۀ به خپل لاسونه خوارۀ کړې او بل څوک به دې ملا وتړى او هغه خوا ته به دې بوځى چرته چې تۀ تلل نۀ غواړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25790, 'John 21:19', 'John', 21, 19, '&nbsp;عيسىٰ دا خبره د دې راز څرګندولو دپاره وکړه چې پطروس به په دغه شان شهيد کړے شى چې د خُدائ پاک جلال به په کښې څرګند شى. بيا عيسىٰ هغۀ ته وفرمائيل چې، ”ما پسې راځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25791, 'John 21:20', 'John', 21, 20, '&nbsp;پطروس راوګرځېدو او هغه مريد يې په ځان پسې راروان وليدلو د چا سره چې عيسىٰ مينه کوله، هغه چې د ماښام د روټۍ په وخت کښې عيسىٰ سره نزدې ناست وو او دا تپوس يې ترېنه کړے وو چې، ”مالِکه، هغه څوک دے چې په تا به مُخبرى کوى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25792, 'John 21:21', 'John', 21, 21, '&nbsp;کله چې پطروس هغه وليدو نو د عيسىٰ نه يې تپوس وکړو، ”مالِکه، د هغۀ اَنجام به څۀ وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25793, 'John 21:22', 'John', 21, 22, '&nbsp;عيسىٰ جواب ورکړو، ”کۀ زۀ وغواړم چې هغه دې تر هغې ژوندے پاتې شى ترڅو چې زۀ بيا راشم نو ستا په دې کښې څۀ؟ تۀ ما پسې راځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25794, 'John 21:23', 'John', 21, 23, '&nbsp;په دې وجه د ايماندارانو په مينځ کښې دا خبره خوره شوه چې دا مريد به نۀ مرى. خو عيسىٰ دا نۀ وُو فرمائيلى چې هغه به نۀ مرى، هغۀ صرف وفرمائيل، ”کۀ زۀ وغواړم چې هغه دې تر هغې ژوندے پاتې شى ترڅو چې زۀ بيا راشم، نو ستا په دې کښې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25795, 'John 21:24', 'John', 21, 24, '&nbsp;دا هغه مريد دے چې د دې هر څۀ ګواهى کوى او دا يې وليکل. مونږ ته پته ده چې د هغۀ ګواهى رښتيا ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25796, 'John 21:25', 'John', 21, 25, '&nbsp;خو نور هم ډېر کارونه دى چې عيسىٰ کړى وُو، کۀ چرې دا ټول ليکلے شوے وے نو زما دا خيال دے چې په ټوله دُنيا کښې به د هغه ليکلے شوو کتابونو ځائ نۀ وے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25797, 'Acts 1:1', 'Acts', 1, 1, '&nbsp;اے تيوفيلوسه، ما په خپل اول کِتاب کښې ټول هغه څۀ وليکل چې عيسىٰ د هغې په کولو او ښودلو شروع وکړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25798, 'Acts 1:2', 'Acts', 1, 2, '&nbsp;د هغۀ آسمان ته د پورته کېدو تر ورځې پورې عيسىٰ د روحُ القُدس په وسيله خپلو غوره شوو رسولانو ته نور هدايات ورکړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25799, 'Acts 1:3', 'Acts', 1, 3, '&nbsp;هغۀ د خپل مرګ نه پس هغوئ ته ځان څرګند کړو او هغوئ ته يې ډېر ثبوتونه پېش کړل چې هغه ژوندے دے او تر څلوېښتو ورځو هغه هغوئ ته ښکاره کېدو او هغوئ ته يې د خُدائ پاک د بادشاهۍ په حقله تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25800, 'Acts 1:4', 'Acts', 1, 4, '&nbsp;ترڅو چې هغه د هغوئ سره وو نو هغۀ هغوئ ته حکم وکړو چې، ”يروشلم مۀ پرېږدئ، بلکې د هغه وعدې انتظار وکړئ چې زما پلار کړې ده، د کومې په حقله چې تاسو زما نه اورېدلى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');